:host {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #e0e0e0;
  --paper: #f9f9f9;
  --font-base: 16px;
  --font-control: 14px;
}

.chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  line-height: 1.6;
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  background: var(--paper);
}

.chapter-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 2rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.chapter-summary {
  font-size: 1.1rem;
  color: var(--muted);
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 2rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.text-block p {
  margin-bottom: 1rem;
  font-size: var(--font-base);
}

.interactive-lab {
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fff;
}

.lab-title {
  font-size: 1.25rem;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.lab-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.5rem;
  align-items: center;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.control-group label {
  font-size: var(--font-control);
  font-weight: 600;
}

input[type="range"] {
  width: 200px;
  accent-color: var(--accent);
}

.switch-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: var(--font-control);
  cursor: pointer;
}

.action-btn {
  padding: 0.5rem 1rem;
  background: var(--ink);
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: var(--font-control);
}

.action-btn:hover {
  background: #333;
}

.visualization-area {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

@media (max-width: 600px) {
  .visualization-area {
    grid-template-columns: 1fr;
  }
}

#geometry-canvas {
  width: 100%;
  height: auto;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fff;
}

.equation-panel {
  padding: 1rem;
  background: var(--paper);
  border-radius: 4px;
  border: 1px solid var(--line);
}

.equation-panel h3 {
  margin: 0 0 0.5rem 0;
  font-size: 1rem;
}

.equation-display {
  font-family: 'Courier New', monospace;
  background: #fff;
  padding: 0.5rem;
  border-radius: 4px;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
  overflow-x: auto;
}

.highlight-term {
  color: var(--warm);
  font-weight: 700;
  cursor: pointer;
  padding: 0 0.25rem;
  border-radius: 2px;
}

.highlight-term.active {
  background: var(--warm);
  color: #000;
}

.equation-note {
  font-size: 0.85rem;
  color: var(--muted);
  margin: 0.5rem 0;
}

.status-box {
  padding: 0.5rem;
  background: #fff;
  border-left: 3px solid var(--accent);
  font-size: 0.9rem;
}

.evidence-column {
  border-left: 1px solid var(--line);
  padding-left: 1.5rem;
}

.evidence-column h3 {
  font-size: 1rem;
  margin: 0 0 1rem 0;
}

.evidence-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.evidence-item {
  margin-bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.source-btn {
  align-self: flex-start;
  padding: 0.25rem 0.5rem;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 0.8rem;
  cursor: pointer;
}

.source-btn:hover {
  border-color: var(--accent);
}

.evidence-text {
  font-size: 0.9rem;
  color: var(--muted);
}

